mod tests {
    use super::ansi_enabled;
    use std::io::IsTerminal;

    /// Verifies that the library disables ANSI color output when stdout
    /// is not a terminal (e.g., piped, redirected, or captured by the
    /// test harness).
    #[test]
    fn ansi_disabled_when_stdout_is_not_a_terminal() {
        // --- Arrange ---
        // Under `cargo test`, stdout is captured and is NOT a TTY.
        // We assert this precondition so the test fails loudly (with a
        // clear message) if someone runs it with `--nocapture` in a real
        // terminal, rather than silently passing or failing for the
        // wrong reason.
        assert!(
            !std::io::stdout().is_terminal(),
            "test precondition failed: stdout must not be a terminal \
             (run via `cargo test` without `--nocapture`)"
        );

        // --- Act & Assert ---
        assert!(
            !ansi_enabled(),
            "ansi_enabled() should return false when stdout is not a terminal"
        );
    }
}
```

### How it works

| Step | What happens |
|------|-------------|
| **Precondition** | `std::io::stdout().is_terminal()` (stable since Rust 1.70) confirms stdout is not a TTY. Under `cargo test`, the harness captures stdout, so this is `false`. |
| **Assertion** | `ansi_enabled()` is expected to internally perform the same kind of terminal check and return `false`. |

### Making the test fully deterministic

If you need the test to pass even when run with `--nocapture` in an interactive terminal, redirect stdout to a pipe explicitly (Unix example using the `libc` crate):

```rust
#[cfg(unix)]
#[test]
fn ansi_disabled_when_stdout_is_piped() {
    use std::os::fd::RawFd;

    // Save real stdout, then point fd 1 at a pipe (non-terminal).
    let saved: RawFd = unsafe { libc::dup(libc::STDOUT_FILENO) };
    let mut fds = [0i32; 2];
    unsafe {
        libc::pipe(fds.as_mut_ptr());
        libc::dup2(fds[1], libc::STDOUT_FILENO);
    }

    let result = ansi_enabled(); // stdout is now a pipe → not a terminal

    // Restore original stdout and close pipe fds.
    unsafe {
        libc::dup2(saved, libc::STDOUT_FILENO);
        libc::close(saved);
        libc::close(fds[0]);
        libc::close(fds[1]);
    }

    assert!(!result, "ANSI should be disabled when stdout is a pipe");
}
```

This version guarantees a non-terminal stdout regardless of how the test is invoked, at the cost of a platform-specific dependency.
